import{_ as t,o as a,a as _,b as d}from"./app.C41L12d5.js";const c="/ascendc.github.io/assets/simt_call.BL8pMLcN.png",m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"高级AI Core编程模型","link":"/guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/advanced_ai_core_programming_model"},{"text":"SIMD与SIMT混合编程","link":"/guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/overview"},{"text":"核函数（Kernel）与VF函数","link":"/guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/kernel_and_vf_functions"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/kernel_and_vf_functions.md","filePath":"guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/kernel_and_vf_functions.md","outlineHeaders":[{"level":2,"title":"核函数（Kernel）的定义与执行配置","slug":"核函数（Kernel）的定义与执行配置","link":"#核函数（Kernel）的定义与执行配置"},{"level":2,"title":"SIMT VF函数","slug":"SIMT-VF函数","link":"#SIMT-VF函数"},{"level":2,"title":"__simt_callee__子函数","slug":"__simt_callee__子函数","link":"#__simt_callee__子函数"}],"lastUpdated":1788515292000}'),l={name:"guide/programming_guide/advanced_programming/advanced_ai_core_programming_model/simd_simt_hybrid_programming/kernel_and_vf_functions.md"};function s(i,e,n,o,r,p){return a(),_("div",null,[...e[0]||(e[0]=[d('<div><article class="markdown-body"><h1>核函数（Kernel）与VF函数<span id="ZH-CN_TOPIC_0000002593909249"></span></h1><p>SIMD与SIMT混合编程涉及多种类型的函数，它们之间遵循严格的调用关系和层级约束。本章节将介绍整体函数类型和调用关系，再详细展开每种函数的定义、调用语法及约束。</p><p>SIMD与SIMT混合编程中涉及的函数类型如下表所示：</p><p><span id="zh-cn_topic_0000002571578013_table1818191292017"></span></p><table><thead><tr><th>修饰符</th><th>函数功能</th><th>调用方式</th></tr></thead><tbody><tr><td><code>__global__ __aicore__</code></td><td>算子入口，协调VF执行。若只有在AIV核内执行的SIMD与SIMT混合编程场景，可使用__global__ __vector__来标识只启动AIV核。</td><td>Host侧通过<code>&lt;&lt;&lt;...&gt;&gt;&gt;</code>调用</td></tr><tr><td><code>__aicore__</code></td><td>Device侧辅助函数</td><td>核函数（Kernel）或同级函数调用</td></tr><tr><td><code>__simt_vf__</code></td><td>线程级并行计算任务</td><td>通过SIMT提供的<code>asc_vf_call</code>接口调用</td></tr><tr><td><code>__simd_vf__</code></td><td>向量级并行计算任务</td><td>通过SIMD提供的<code>asc_vf_call</code>接口调用</td></tr><tr><td><code>__simt_callee__</code></td><td>SIMT VF的子函数</td><td>SIMT VF内部调用</td></tr><tr><td><code>__simd_callee__</code></td><td>SIMD VF的子函数</td><td>SIMD VF内部调用</td></tr><tr><td><code>__callee__</code></td><td>SIMD VF和SIMT VF的公共子函数</td><td>VF内部调用</td></tr></tbody></table><p>各层函数间的调用关系如下：</p><ul><li>核函数（Kernel）：是Device侧的入口函数，可以调用<code>__aicore__</code>函数和VF函数。</li><li>simd vf函数：能被核函数（Kernel）或者<code>__aicore__</code>函数通过<code>asc_vf_call</code>接口调用。simd vf函数内只能调用<code>__simd_callee__</code>函数和<code>__callee__</code>函数。</li><li>simt vf函数：使用__simt_vf__标记，能被核函数（Kernel）或者<code>__aicore__</code>函数通过<code>asc_vf_call</code>接口调用。simt vf函数内只能调用<code>__simt_callee__</code>函数和<code>__callee__</code>函数。</li><li><code>__simd_callee__</code>子函数：simd vf函数内部的子函数，子函数可能有返回值或者通过引用传参。__simd_callee__函数内只能调用<code>__simd_callee__</code>函数和<code>__callee__</code>函数。</li><li><code>__simt_callee__</code>子函数：simt vf函数内部的子函数，子函数可能有返回值或者通过引用传参。<code>__simt_callee__</code>函数内只能调用<code>__simt_callee__</code>函数和<code>__callee__</code>函数。</li><li><code>__callee__</code>公共函数：可供VF内部调用的公共子函数。<code>__callee__</code>函数内只能调用<code>__callee__</code>函数。</li></ul><p><strong>图1</strong> SIMD与SIMT混合编程函数调用层级<br><img src="'+c+`" title="SIMD与SIMT混合编程函数调用层级"></p><h2 id="核函数（Kernel）的定义与执行配置">核函数（Kernel）的定义与执行配置<span id="zh-cn_topic_0000002571578013_section156822920311"></span><a class="header-anchor" href="#核函数（Kernel）的定义与执行配置">​</a></h2><p>核函数（Kernel）是SIMD与SIMT混合编程的Device侧入口函数，负责协调整个算子的执行流程，包括VF的调度和调用。函数定义语法为：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>__global__ __vector__ void kernel_name(__gm__ type* param1, __gm__ type* param2, ...);
</code></pre></div><p>关键修饰符说明如下：</p><p><span id="zh-cn_topic_0000002571578013_table4811406341"></span></p><table><thead><tr><th>修饰符</th><th>作用</th><th>必需性</th></tr></thead><tbody><tr><td><code>__global__</code></td><td>标识核函数（Kernel），表明可在Host侧通过<code>&lt;&lt;&lt;...&gt;&gt;&gt;</code>调用</td><td>必需</td></tr><tr><td><code>__vector__</code></td><td>标识函数是在Device侧AI Vector上执行</td><td>必需</td></tr></tbody></table><p>核函数（Kernel）定义有以下几个约束：</p><ul><li>返回值类型必须是void；</li><li>入参支持指针类型（需使用__gm__修饰）和Ascend C内置数据类型；</li><li>指针参数必须是指向Global Memory上的内存地址，使用__gm__修饰。</li></ul><p>核函数（Kernel）的调用是通过&lt;&lt;&lt;...&gt;&gt;&gt;核函数（Kernel）调用符在Host侧调用，语法如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>kernel_name&lt;&lt;&lt;block_num, dyn_ub_size, stream&gt;&gt;&gt;(args...);
</code></pre></div><p>核函数（Kernel）调用符内的配置参数说明如下：</p><p><span id="zh-cn_topic_0000002571578013_table942016184315"></span></p><table><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>约束</th></tr></thead><tbody><tr><td><code>block_num</code></td><td><code>uint32_t</code></td><td>设置核函数（Kernel）启用的核数</td><td>取值范围[1, 65535]</td></tr><tr><td><code>dyn_ub_size</code></td><td><code>uint32_t</code></td><td>指定动态内存大小，单位为字节</td><td>不超过最大可配置值：256KB - 8KB - 32KB - 静态内存</td></tr><tr><td><code>stream</code></td><td><code>aclrtStream</code></td><td>用于维护异步操作执行顺序</td><td>无</td></tr></tbody></table><h2 id="SIMT-VF函数">SIMT VF函数<span id="zh-cn_topic_0000002571578013_section1780955884616"></span><a class="header-anchor" href="#SIMT-VF函数">​</a></h2><p>SIMT VF函数用于实现线程级并行计算任务，处理不规则访问和复杂控制逻辑，函数内可使用SIMT内置变量：threadIdx、blockIdx、blockDim、gridDim。函数定义示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>__simt_vf__ __launch_bounds__(MAX_THREAD_COUNT) inline void function_name(
    __gm__ type* gm_param,
    __ubuf__ type* ubuf_param,
    type scalar_param, ...);
</code></pre></div><p>SIMT VF函数定义中的关键修饰符说明如下：</p><p><span id="zh-cn_topic_0000002571578013_table7661145014492"></span></p><table><thead><tr><th>修饰符</th><th>作用</th></tr></thead><tbody><tr><td><code>__simt_vf__</code></td><td>函数标识符，标识SIMT VF函数</td></tr><tr><td><code>__launch_bounds__(N)</code></td><td>指定最大线程数（可选，默认1024）</td></tr><tr><td><code>inline</code></td><td>建议内联，实际是否内联由编译器决定</td></tr><tr><td><code>__gm__</code></td><td>内存空间修饰符，标识内存空间为GM</td></tr><tr><td><code>__ubuf__</code></td><td>内存空间修饰符，标识内存空间为UB</td></tr></tbody></table><p>通过SIMT的<a href="../../../../../api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/extended_syntax/kernel_function_config.html#asc-vf-call">asc_vf_call</a>接口在核函数（Kernel）或__aicore__函数中调用，调用示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">uint32_t</span><span class="w"> </span><span class="n">thread_num</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1024</span><span class="p">;</span>
<span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">function_name</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dim3</span><span class="p">(</span><span class="n">thread_num</span><span class="p">),</span><span class="w"> </span><span class="n">arg1</span><span class="p">,</span><span class="w"> </span><span class="n">arg2</span><span class="p">,</span><span class="w"> </span><span class="p">...);</span>
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>与SIMT编程场景中在核函数（Kernel）调用符内配置线程数不同，混合编程场景中SIMT线程配置通过asc_vf_call接口的第一个参数配置。</p></div><p>SIMT VF函数有以下约束：</p><ul><li>入参仅支持Ascend C的<a href="../../../language_extension/simd_simt_hybrid_builtin_keywords.html#zh-cn_topic_0000002571575581_section1880403364916">内置数据类型</a>（int32_t、uint32_t、float、half等）及其组成的指针、数组、结构体类型，且指针类型必须指向GM或者Unified Buffer（UB）内存。</li><li>不支持将核函数（Kernel）中局部变量的地址或引用传递给VF函数。</li><li>函数返回类型必须是void。</li><li>SIMT VF内只能调用__simt_callee__函数或__callee__函数。</li></ul><h2 id="__simt_callee__子函数">__simt_callee__子函数<span id="zh-cn_topic_0000002571578013_section4680126514"></span><a class="header-anchor" href="#__simt_callee__子函数">​</a></h2><p>__simt_callee__子函数是SIMT VF函数内部调用的辅助函数，函数内部可以使用SIMT内置变量。定义示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>__simt_callee__ return_type function_name(__gm__ type* gm_param, __ubuf__ type* ubuf_param, type scalar_param, ...);
</code></pre></div><p>调用示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>return_type result = function_name(arg1, arg2, ...);
</code></pre></div><p>该函数有以下约束：</p><ul><li>入参仅支持Ascend C的<a href="../../../language_extension/simd_simt_hybrid_builtin_keywords.html#zh-cn_topic_0000002571575581_section1880403364916">内置数据类型</a>（int32_t、uint32_t、float、half等）和指针类型。</li><li>函数返回值只能是Ascend C的<a href="../../../language_extension/simd_simt_hybrid_builtin_keywords.html#zh-cn_topic_0000002571575581_section1880403364916">内置数据类型</a>（int32_t、uint32_t、float、half等）及对应的指针类型。</li><li>函数内只能调用__simt_callee__函数或__callee__函数。</li></ul></article></div>`,1)])])}const g=t(l,[["render",s]]);export{m as __pageData,g as default};
